988	    private stopHoloPulsar() {
989	        if (this.holoAnim) cancelAnimationFrame(this.holoAnim);
990	        if (this.holoCtx) {
991	            const canvas = this.holoCtx.canvas;
992	            this.holoCtx.clearRect(0, 0, canvas.width, canvas.height);
993	        }
994	    }
