999	    neuralPulse(freq: number = 440, type: OscillatorType = 'sine', duration: number = 0.1) {
1000	        try {
1001	            const AudioContext = (window as any).AudioContext || (window as any).webkitAudioContext;
1002	            const ctx = new AudioContext();
1003	            const osc = ctx.createOscillator();
1004	            const gain = ctx.createGain();
1005	
1006	            osc.type = type;
1007	            osc.frequency.setValueAtTime(freq, ctx.currentTime);
1008	            
1009	            gain.gain.setValueAtTime(0.05, ctx.currentTime);
1010	            gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + duration);
1011	
1012	            osc.connect(gain);
1013	            gain.connect(ctx.destination);
1014	
1015	            osc.start();
1016	            osc.stop(ctx.currentTime + duration);
1017	        } catch (e) {}
1018	    }
